// src/pages/Profile.jsx
import { useState } from "react";
import C from "../constants/colors";
import { STATES_TN_DISTRICTS } from "../constants/crops";
import S from "../utils/storage";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Btn from "../components/ui/Btn";
import Input from "../components/ui/Input";

export default function Profile({ user, onLogout, onUpdate }) {
  const [edit, setEdit] = useState(false);
  const [form, setForm] = useState({
    name: user.name,
    district: user.district,
    landSize: user.landSize || "",
    language: user.language || "Tamil",
  });

  const f = (k) => (e) => setForm(p => ({ ...p, [k]: e.target.value }));

  const save = () => {
    const users = S.get("users") || [];
    const idx = users.findIndex(u => u.id === user.id);
    const updated = { ...user, ...form, landSize: parseFloat(form.landSize) || 0 };
    if (idx >= 0) { users[idx] = updated; S.set("users", users); S.set("current_user", updated); }
    onUpdate(updated);
    setEdit(false);
  };

  return (
    <div style={{ padding: 22, maxWidth: 600 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 16px" }}>👤 My Profile</h1>

      {/* Profile Card */}
      <Card style={{ marginBottom: 14 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
          <div style={{ width: 60, height: 60, borderRadius: "50%", background: C.bg2, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22, fontWeight: 700 }}>
            {user.name.slice(0, 2).toUpperCase()}
          </div>
          <div>
            <div style={{ fontSize: 18, fontWeight: 600, color: C.text }}>{user.name}</div>
            <div style={{ fontSize: 13, color: C.muted }}>{user.phone} • Joined {new Date(user.createdAt).toLocaleDateString("en-IN")}</div>
            <Badge>{user.district}, TN</Badge>
          </div>
        </div>

        {edit ? (
          <>
            <Input label="Full Name" value={form.name} onChange={f("name")} />
            <Input label="District" value={form.district} onChange={f("district")} options={STATES_TN_DISTRICTS} />
            <Input label="Land Size (Acres)" type="number" value={form.landSize} onChange={f("landSize")} />
            <Input label="Preferred Language" value={form.language} onChange={f("language")} options={["Tamil", "English", "Hindi"]} />
            <div style={{ display: "flex", gap: 8 }}>
              <Btn onClick={save}>Save Changes</Btn>
              <Btn variant="ghost" onClick={() => setEdit(false)}>Cancel</Btn>
            </div>
          </>
        ) : (
          <>
            {[
              ["Mobile",    user.phone],
              ["District",  user.district],
              ["State",     "Tamil Nadu"],
              ["Land Size", `${user.landSize || "Not set"} acres`],
              ["Language",  user.language || "Tamil"],
            ].map(([l, v]) => (
              <div key={l} style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderBottom: `1px solid ${C.border}`, fontSize: 13 }}>
                <span style={{ color: C.muted }}>{l}</span>
                <span style={{ color: C.text, fontWeight: 500 }}>{v}</span>
              </div>
            ))}
            <div style={{ marginTop: 14, display: "flex", gap: 8 }}>
              <Btn onClick={() => setEdit(true)} variant="outline">✏️ Edit Profile</Btn>
              <Btn onClick={onLogout} variant="danger">Logout</Btn>
            </div>
          </>
        )}
      </Card>

      {/* Crops Card */}
      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>🌾 My Crops ({user.crops?.length || 0})</div>
        {user.crops?.length
          ? <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>{user.crops.map(c => <Badge key={c}>{c}</Badge>)}</div>
          : <div style={{ fontSize: 13, color: C.muted }}>No crops registered. Update profile to add crops.</div>
        }
      </Card>

      {/* Disease History */}
      {user.diseaseHistory?.length > 0 && (
        <Card>
          <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>🔬 Recent Disease History</div>
          {user.diseaseHistory.slice(0, 5).map((d, i) => (
            <div key={i} style={{ display: "flex", justifyContent: "space-between", padding: "6px 0", borderBottom: i < 4 ? `1px solid ${C.border}` : "none", fontSize: 12.5 }}>
              <span style={{ color: C.text }}>{d.crop} — {d.disease}</span>
              <span style={{ color: C.muted }}>{d.date}</span>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}
